    source:
      "//! Bounded byte transfer coupled to retained input and exact-prefix buffered output.\n\nimport silk.buffered_duplex {BufferedDuplex}\nimport silk.buffered_input {BufferError, FillOutcome}\nimport silk.byte_duplex {ByteDuplex}\nimport silk.effect {Effect}\nimport silk.monotonic_clock {MonotonicClock}\nimport silk.option {Option}\nimport silk.result {Result}\nimport silk.slice {Slice}\nimport silk.system_clock {Instant, SystemClock}\nimport silk.usize\n\n/// One finite transfer result.\npub struct TransferOutcome {\n  /// The exact destination-accepted and source-consumed count.\n  pub count: usize\n  /// True only when the operation actually observed source end.\n  pub endObserved: bool\n}\n\n/// The owner of bounded exact-prefix transfer operations.\npub struct BufferedTransfer {}\n\nimpl BufferedTransfer {\n/// Transfers no more than `limit`, consuming only destination-accepted bytes.\npub effect fn transferAtMost<'source, 'destination, SP, DP>(\n  source: &mut BufferedDuplex<'source, SP>,\n  destination: &mut BufferedDuplex<'destination, DP>,\n  limit: usize,\n  deadline: Option<Instant>,\n) -> TransferOutcome\n! BufferError\n? &mut MonotonicClock\nwhere &mut SP provides &ByteDuplex from &mut ByteDuplex | &mut MonotonicClock,\n  &mut DP provides &ByteDuplex from &mut ByteDuplex | &mut MonotonicClock {\n  let mut transferred = usize.ZERO\n  while transferred < limit {\n    let filling = run Effect.result(BufferedDuplex.fill(\n      &mut source.*,\n      usize.ONE,\n      copyDeadline(&deadline),\n    ))\n    let fill = match move filling {\n      Result<FillOutcome, BufferError>.Success {value} => move value\n      Result<FillOutcome, BufferError>.Failure {error} => {\n        fail addProgress(move error, transferred)\n      }\n    }\n    let unread = BufferedDuplex.unread(&source.*)\n    if unread == usize.ZERO {\n      drop fill\n      return TransferOutcome {count: transferred, endObserved: true}\n    }\n    let count = minimum(unread, limit - transferred)\n    let available = BufferedDuplex.peek(&source.*)\n    let offered = Slice.view<u8>(available, usize.ZERO, count)\n    let writing = run Effect.result(BufferedDuplex.writeSome(\n      &mut destination.*,\n      offered,\n      copyDeadline(&deadline),\n    ))\n    drop offered\n    drop available\n    let accepted = match move writing {\n      Result<usize, BufferError>.Success {value} => value\n      Result<usize, BufferError>.Failure {error} => {\n        fail addProgress(move error, transferred)\n      }\n    }\n    run BufferedDuplex.consume(&mut source.*, accepted)\n    transferred = transferred + accepted\n    drop fill\n  }\n  return TransferOutcome {count: transferred, endObserved: false}\n}\n\n/// Transfers exactly `count` bytes or reports early end with the transferred prefix.\npub effect fn transferExact<'source, 'destination, SP, DP>(\n  source: &mut BufferedDuplex<'source, SP>,\n  destination: &mut BufferedDuplex<'destination, DP>,\n  count: usize,\n  deadline: Option<Instant>,\n) -> ()\n! BufferError\n? &mut MonotonicClock\nwhere &mut SP provides &ByteDuplex from &mut ByteDuplex | &mut MonotonicClock,\n  &mut DP provides &ByteDuplex from &mut ByteDuplex | &mut MonotonicClock {\n  let outcome = run BufferedTransfer.transferAtMost(\n    move source,\n    move destination,\n    count,\n    move deadline,\n  )\n  if outcome.count != count {\n    fail BufferError.UnexpectedEnd {progress: outcome.count}\n  }\n  return ()\n}\n}\n\nfn minimum(left: usize, right: usize) -> usize {\n  if left < right { return left }\n  return right\n}\n\nfn copyInstant(value: &Instant) -> Instant {\n  return SystemClock.make(SystemClock.seconds(value), SystemClock.nanoseconds(value))\n}\n\nfn copyDeadline(value: &Option<Instant>) -> Option<Instant> {\n  return match &value.* {\n    Option<Instant>.None => Option.none<Instant>()\n    Option<Instant>.Some {value: present} => Option.some<Instant>(copyInstant(&present))\n  }\n}\n\nfn addProgress(failure: BufferError, prior: usize) -> BufferError {\n  return match move failure {\n    BufferError.ReadFailed {progress, error: cause} => BufferError.ReadFailed {\n      progress: prior + progress,\n      error: move cause,\n    }\n    BufferError.InputFailed {progress, error: cause} => BufferError.InputFailed {\n      progress: prior + progress,\n      error: move cause,\n    }\n    BufferError.WriteFailed {accepted, drained, error: cause} => BufferError.WriteFailed {\n      accepted: prior + accepted,\n      drained: drained,\n      error: move cause,\n    }\n    BufferError.UnknownExternalTransfer {progress, error: cause} => BufferError.UnknownExternalTransfer {\n      progress: prior + progress,\n      error: move cause,\n    }\n    BufferError.UnexpectedEnd {progress} => BufferError.UnexpectedEnd {progress: prior + progress}\n    BufferError.InvalidCapacity {capacity} => BufferError.InvalidCapacity {capacity: capacity}\n    BufferError.BufferTooSmall {requested, capacity} => BufferError.BufferTooSmall {\n      requested: requested,\n      capacity: capacity,\n    }\n    BufferError.InvalidConsumption {requested, available} => BufferError.InvalidConsumption {\n      requested: requested,\n      available: available,\n    }\n    BufferError.InvalidReadCount {count, limit} => BufferError.InvalidReadCount {\n      count: count,\n      limit: limit,\n    }\n    BufferError.LengthOverflow => BufferError.LengthOverflow\n    BufferError.Terminal => BufferError.Terminal\n  }\n}\n",
