n  /// Success does not verify signatures, trust, names, or current validity. Extensions remain opaque.\n  pub effect fn decodeDer(input: &[u8], limits: DecodeLimits) -> Result<Certificate, DecodeError>\n  ! OutOfMemoryError\n  ? &mut Allocator {\n    if input.length > limits.inputBytes {\n      return Result.failResult<Certificate, DecodeError>(\n        errorAt(DecodeClass.ResourceLimit, DecodeReason.InputBytes, limits.inputBytes),\n      )\n    }\n    if input.length == 0 {\n      return Result.failResult<Certificate, DecodeError>(\n        errorAt(DecodeClass.Malformed, DecodeReason.EmptyInput, 0),\n      )\n    }\n    if limits.certificates == 0 {\n      return Result.failResult<Certificate, DecodeError>(\n        errorAt(DecodeClass.ResourceLimit, DecodeReason.Certificates, 0),\n      )\n    }\n    let mut reader = Reader {\n      bytes: input,\n      limits: limits,\n      cursor: 0,\n      nodes: 0,\n      failed: false,\n      error: errorAt(DecodeClass.Malformed, DecodeReason.Schema, 0),\n    }\n    let mut extensions = Vector.make<Extension>()\n    let fields = run schema(&mut reader, &mut extensions)\n    if reader.failed {\n      return Result.failResult<Certificate, DecodeError>(reader.error)\n    }\n    let bytes = run Bytes.copy(input)\n    return Result.succeed<Certificate, DecodeError>(\n      Certificate {bytes: move bytes, fields: fields, extensions: move extensions},\n    )\n  }\n  /// Decodes exactly one strict CERTIFICATE PEM block into independent owned storage.\n  ///\n  /// # Details\n  ///\n  /// The parser accepts SP, HT, LF, CRLF, and CR whitespace, with canonical base64 padding and pad bits.\n  /// Other labels are unsupported. Text outside markers, malformed markers, and a second block fail.\n  /// Allocation refusal uses `OutOfMemoryError`; no partial certificate escapes.\n  ///\n  /// # Gotchas\n  ///\n  /// This strict profile rejects explanatory text and VT/FF that permissive RFC 7468 readers can ignore.\n  /// Success does not est