    module: 'silk/host_input',
    path: 'silk/host_input.silk',
    sourceIdentity: 'silk/host_input',
    digest: 'd4cdb1ca294cb741d25a3f5501901dee7a7c6ebe7d4c01aedddf4d67ad23fbed',
    documentation: 'silk/host_input.silk',
    staticInventory: [],
