    source:
      '//! Serial native admission for one scoped HTTP server connection.\n//!\n//! # Details\n//!\n//! `serveNext` accepts exactly one connection and lends the portable server actor inside the same\n//! accepted-owner scope. Applications repeat the operation explicitly; this module creates no\n//! background queue, router, supervisor, or detached task.\n\nstatic if (Intrinsic.targetOperatingSystem() == "darwin"\n  && Intrinsic.targetArchitecture() == "aarch64"\n  && Intrinsic.targetAbi() == "apple"\n  && Intrinsic.profileText("libc") == "system")\n  || (Intrinsic.targetOperatingSystem() == "linux"\n    && Intrinsic.targetAbi() == "gnu"\n    && Intrinsic.profileText("libc") == "gnu"\n    && (Intrinsic.targetArchitecture() == "aarch64"\n      || Intrinsic.targetArchitecture() == "x86_64")) {\n  import silk.allocator {Allocator, OutOfMemoryError}\n  import silk.buffered_input {BufferError}\n  import silk.byte_duplex {ByteDuplex}\n  import silk.effect {Effect}\n  import silk.http_server {\n    ConnectionHandler,\n    Limits,\n    ServerError,\n    withConnection,\n  }\n  import silk.monotonic_clock {MonotonicClock}\n  import silk.native_socket {\n    AcceptedContext,\n    AcceptedView,\n    Connection as NativeConnection,\n    Listener,\n    NativeSocketError,\n    accept,\n    withAcceptedContext,\n  }\n  import silk.system_clock {Instant}\n  import silk.option {Option}\n\n  /// Namespace anchor for native HTTP admission.\n  pub struct HttpServerNative {}\n\n  struct ServerAcceptedContext<A, E, ?HandlerRequirements, H> {\n    limits: Limits\n    handler: H\n  }\n\n  impl<A, E, ?HandlerRequirements, OuterH>\n    ServerAcceptedContext<A, E, HandlerRequirements, OuterH> {\n    effect<\'call> fn use<\n      \'call,\n      H: ConnectionHandler<NativeConnection, A, E ? HandlerRequirements>,\n    >(\n      context: ServerAcceptedContext<A, E, HandlerRequirements, H>,\n      view: &\'call mut AcceptedView<\'call>,\n    ) -> A\n    ! E | ServerError | BufferError | OutOfMemoryError\n    ? HandlerRequirements | &mut Allocator | &mut MonotonicClock\n    where HandlerRequirements in Without<HandlerRequirements, ByteDuplex> {\n      let ServerAcceptedContext<A, E, HandlerRequirements, H> {limits, handler} = move context\n      return run withConnection<A, E, HandlerRequirements, NativeConnection>(\n        &mut view.connection.*,\n        limits,\n        move handler,\n      )\n    }\n  }\n\n  impl<\n    A,\n    E,\n    ?HandlerRequirements,\n    H: ConnectionHandler<NativeConnection, A, E ? HandlerRequirements>,\n  > AcceptedContext<\n    A,\n    E | ServerError | BufferError | OutOfMemoryError,\n    HandlerRequirements\n    ? &mut Allocator | &mut MonotonicClock\n  > for ServerAcceptedContext<A, E, HandlerRequirements, H> {\n    use: ServerAcceptedContext.use\n  }\n\n  /// Accepts and serves exactly one connection inside the listener\'s accepted-owner scope.\n  pub effect<\'env> fn serveNext<\n    \'listener,\n    A,\n    E,\n    ?HandlerRequirements,\n    H: ConnectionHandler<NativeConnection, A, E ? HandlerRequirements> + \'env,\n    \'env,\n  >(\n    listener: &\'listener mut Listener,\n    limits: Limits,\n    acceptDeadline: Option<Instant>,\n    handler: H,\n  ) -> A\n  ! E | NativeSocketError | ServerError | BufferError | OutOfMemoryError\n  ? HandlerRequirements | &mut Allocator | &mut MonotonicClock\n  where HandlerRequirements in Without<HandlerRequirements, ByteDuplex> {\n    let accepted = run accept(move listener, move acceptDeadline)\n    let context = ServerAcceptedContext<A, E, HandlerRequirements, H> {\n      limits: limits,\n      handler: move handler,\n    }\n    return run withAcceptedContext<\n      A,\n      E | ServerError | BufferError | OutOfMemoryError,\n      HandlerRequirements,\n    >(move accepted, move context)\n  }\n}\n',
