    source:
      '//! Decoding validated JSON string tokens into owned UTF-8 bytes.\n//!\n//! # When to use\n//! Use [`JsonText.decode`] after `JsonScanner` has validated a string token. The returned bytes\n//! are valid UTF-8 and can be adopted by `String` without another copy.\n\nimport silk.allocator { Allocator, OutOfMemoryError }\nimport silk.bytes { Bytes }\nimport silk.json_scanner { JsonError, JsonReason }\nimport silk.slice { Slice }\nimport silk.u32\nimport silk.u8\nimport silk.usize\n\n/// Operations on validated JSON string token text.\npub struct JsonText {}\n\nimpl JsonText {\n  /// Copies scanner-validated UTF-8 or ASCII bytes into owned storage.\n  pub effect fn copy(raw: &[u8]) -> Bytes ! OutOfMemoryError ? &mut Allocator {\n    let mut output = Bytes.make()\n    run Bytes.append(&mut output, raw)\n    return move output\n  }\n\n  /// Decodes one quoted token, including escapes, into owned valid UTF-8 bytes.\n  pub effect fn decode(raw: &[u8], offset: usize, escaped: bool)\n    -> Bytes ! JsonError | OutOfMemoryError ? &mut Allocator {\n    if raw.length < 2 { fail JsonError.at(JsonReason.UnterminatedString, offset) }\n    let contents = Slice.view<u8>(raw, usize.ONE, raw.length - 2)\n    if !escaped { return run JsonText.copy(contents) }\n    let mut output = Bytes.make()\n    run Bytes.reserveExact(&mut output, contents.length)\n    let mut index = usize.ZERO\n    let mut start = usize.ZERO\n    while index < contents.length {\n      if contents[index] != 92 {\n        index = index + usize.ONE\n        continue\n      }\n      if start < index {\n        run Bytes.append(&mut output, Slice.view<u8>(contents, start, index - start))\n      }\n      let escapeStart = index\n      index = index + usize.ONE\n      if index >= contents.length {\n        fail JsonError.at(JsonReason.InvalidEscape, offset + escapeStart + usize.ONE)\n      }\n      let escapedByte = contents[index]\n      if escapedByte == 117 {\n        if index + 4 >= contents.length {\n          fail JsonError.at(JsonReason.InvalidEscape, offset + escapeStart + usize.ONE)\n        }\n        let first = readHex(contents, index + usize.ONE)\n        let mut scalar = first\n        index = index + 5\n        if first >= 55296 && first <= 56319 {\n          if index + 5 >= contents.length || contents[index] != 92 || contents[index + usize.ONE] != 117 {\n            fail JsonError.at(JsonReason.InvalidEscape, offset + escapeStart + usize.ONE)\n          }\n          let low = readHex(contents, index + 2)\n          if low < 56320 || low > 57343 {\n            fail JsonError.at(JsonReason.InvalidEscape, offset + index + usize.ONE)\n          }\n          scalar = 65536 + (first - 55296) * 1024 + (low - 56320)\n          index = index + 6\n        } else if first >= 56320 && first <= 57343 {\n          fail JsonError.at(JsonReason.InvalidEscape, offset + escapeStart + usize.ONE)\n        }\n        run appendScalar(&mut output, scalar)\n      } else {\n        let mut decoded = escapedByte\n        if escapedByte == 98 { decoded = 8 }\n        else if escapedByte == 102 { decoded = 12 }\n        else if escapedByte == 110 { decoded = 10 }\n        else if escapedByte == 114 { decoded = 13 }\n        else if escapedByte == 116 { decoded = 9 }\n        else if escapedByte != 34 && escapedByte != 47 && escapedByte != 92 {\n          fail JsonError.at(JsonReason.InvalidEscape, offset + escapeStart + usize.ONE)\n        }\n        let one = [decoded]\n        run Bytes.append(&mut output, &one)\n        index = index + usize.ONE\n      }\n      start = index\n    }\n    if start < contents.length {\n      run Bytes.append(&mut output, Slice.view<u8>(contents, start, contents.length - start))\n    }\n    // The scanner validated raw UTF-8 and every decoded escape is a Unicode scalar.\n    return move output\n  }\n}\n\nfn readHex(raw: &[u8], start: usize) -> u32 {\n  let mut total: u32 = 0\n  let mut index = start\n  while index < start + 4 {\n    let byte = raw[index]\n    let mut digit = u8.toU32(byte - u8.toU8(48))\n    if byte >= 65 && byte <= 70 { digit = u8.toU32(byte - u8.toU8(65)) + 10 }\n    if byte >= 97 && byte <= 102 { digit = u8.toU32(byte - u8.toU8(97)) + 10 }\n    total = total * 16 + digit\n    index = index + usize.ONE\n  }\n  return total\n}\n\neffect fn appendScalar(output: &mut Bytes, scalar: u32) -> () ! OutOfMemoryError ? &mut Allocator {\n  if scalar < 128 {\n    let encoded = [u32.toU8(scalar)]\n    return run Bytes.append(&mut output.*, &encoded)\n  }\n  if scalar < 2048 {\n    let encoded = [u32.toU8(192 + scalar / 64), u32.toU8(128 + scalar % 64)]\n    return run Bytes.append(&mut output.*, &encoded)\n  }\n  if scalar < 65536 {\n    let encoded = [u32.toU8(224 + scalar / 4096),\n      u32.toU8(128 + scalar / 64 % 64), u32.toU8(128 + scalar % 64)]\n    return run Bytes.append(&mut output.*, &encoded)\n  }\n  let encoded = [u32.toU8(240 + scalar / 262144),\n    u32.toU8(128 + scalar / 4096 % 64),\n    u32.toU8(128 + scalar / 64 % 64), u32.toU8(128 + scalar % 64)]\n  return run Bytes.append(&mut output.*, &encoded)\n}\n',
