    module: 'silk/native_file_trust_source',
    path: 'silk/native_file_trust_source.silk',
    sourceIdentity: 'silk/native_file_trust_source',
    digest: '70fb857a58ac33af34e27a40cc936ce3d72b8a3f803e0f01c0f2de436d912de9',
