    source:
      '//! Source-owned startup for a hosted native executable.\n//!\n//! # When to use\n//!\n//! Select this module as the runtime root for Darwin ARM64 or GNU Linux x86-64/ARM64.\n//! It supplies the platform C main entry and calls the explicitly selected application module.\n//!\n//! # Details\n//!\n//! The application returns i32, unit, or an Effect producing unit or i32. The Effect may require mutable\n//! HostInput; startup provides an owned argument/environment snapshot. Other requirements must\n//! be supplied by application source. Returned and directly authored Effects use the same policy.\n//!\n//! Application execution owns a 64-node diagnostic pool with 4096 output bytes and 32 frames.\n//! Initialization uses allocation-free fallback diagnostics. Typed failures return status 1 after\n//! payload cleanup, even when reporting cannot allocate or write. Fatal traps do not unwind.\n//!\n//! # Gotchas\n//!\n//! Startup supplies no scheduler or event loop. A park-capable application must establish its own\n//! execution owner; the application closure is checked with Intrinsic.NonParking.\n\nstatic if (Intrinsic.targetOperatingSystem() == "darwin" && Intrinsic.targetArchitecture() == "aarch64" && Intrinsic.targetAbi() == "apple" && Intrinsic.profileText(\n  "libc",\n) == "system") || (Intrinsic.targetOperatingSystem() == "linux" && Intrinsic.targetAbi() == "gnu" && Intrinsic.profileText(\n  "libc",\n) == "gnu" && (Intrinsic.targetArchitecture() == "aarch64" || Intrinsic.targetArchitecture() == "x86_64")) {\n  import Intrinsic.application\n\n  import silk.effect {Effect}\n\n  import silk.native_diagnostics {NativeDiagnostics}\n\n  import silk.native_report {NativeReport}\n\n  import silk.usize\n\n  import silk.host_input {HostInput, HostInputError}\n\n  import silk.native_host_input {NativeHostInput}\n\n  import silk.os_host_input {OsHostInput}\n  struct Application<T> {}\n  interface EntryResult<T> {\n    fn code(value: T, inputs: &mut OsHostInput) -> i32\n  }\n  impl EntryResult<i32> for Application<i32> {\n    fn code(value: i32, inputs: &mut OsHostInput) -> i32 {\n      return value\n    }\n  }\n  impl EntryResult<()> for Application<()> {\n    fn code(value: (), inputs: &mut OsHostInput) -> i32 {\n      return 0\n    }\n  }\n  effect<\'env> fn failed<E: \'env, \'env>(error: E) -> i32 {\n    drop error\n    return usize.toI32(Intrinsic.observeUnhandled())\n  }\n  effect fn succeeded(value: ()) -> i32 {\n    return 0\n  }\n  effect fn succeededStatus(value: i32) -> i32 {\n    return value\n  }\n  impl<\'env, E> EntryResult<Effect<\'env; () ! E>> for Application<Effect<\'env; () ! E>> {\n    fn code(value: Effect<\'env; () ! E>, inputs: &mut OsHostInput) -> i32 {\n      let computation = Effect.flatMap(move value, succeeded)\n      return run Effect.catchAll(move computation, failed)\n    }\n  }\n  impl<\'env, E> EntryResult<Effect<\'env; () ! E ? &mut HostInput>> for Application<\n    Effect<\'env; () ! E ? &mut HostInput>,\n  > {\n    fn code(value: Effect<\'env; () ! E ? &mut HostInput>, inputs: &mut OsHostInput) -> i32 {\n      let supplied = Effect.provideMut<HostInput>(move value, move inputs)\n      let computation = Effect.flatMap(move supplied, succeeded)\n      return run Effect.catchAll(move computation, failed)\n    }\n  }\n  impl<\'env, E> EntryResult<Effect<\'env; i32 ! E>> for Application<Effect<\'env; i32 ! E>> {\n    fn code(value: Effect<\'env; i32 ! E>, inputs: &mut OsHostInput) -> i32 {\n      let computation = Effect.flatMap(move value, succeededStatus)\n      return run Effect.catchAll(move computation, failed)\n    }\n  }\n  impl<\'env, E> EntryResult<Effect<\'env; i32 ! E ? &mut HostInput>> for Application<\n    Effect<\'env; i32 ! E ? &mut HostInput>,\n  > {\n    fn code(value: Effect<\'env; i32 ! E ? &mut HostInput>, inputs: &mut OsHostInput) -> i32 {\n      let supplied = Effect.provideMut<HostInput>(move value, move inputs)\n      let computation = Effect.flatMap(move supplied, succeededStatus)\n      return run Effect.catchAll(move computation, failed)\n    }\n  }\n  fn select<T>(value: &T) -> Application<T> {\n    return Application<T> {}\n  }\n  fn adapt<T, P: EntryResult<T>>(value: T, provider: P, inputs: &mut OsHostInput) -> i32 {\n    return EntryResult<T>.code(move value, inputs)\n  }\n\n  import silk.allocator {Allocator, OutOfMemoryError}\n\n  import silk.execution {Execution}\n  struct EntrySuspended {}\n  struct Status {\n    complete: bool\n    code: i32\n  }\n  fn ready(state: &()) -> () {}\n  fn complete(state: &mut Status, code: i32) -> () {\n    state.complete = true\n    state.code = code\n  }\n  fn suspended(state: &mut Status, execution: Intrinsic.Execution<i32>) -> () {\n    drop execution\n    return ()\n  }\n  fn invokeApplication(inputs: OsHostInput) -> i32 {\n    let mut host = move inputs\n    let value = application.main()\n    let provider = select(&value)\n    return adapt(move value, move provider, &mut host)\n  }\n  fn invoke<F: fn<\'static>(OsHostInput) -> i32 + Intrinsic.NonParking>(body: F, inputs: OsHostInput) -> i32 {\n    return body(move inputs)\n  }\n  effect fn observedApplication(inputs: OsHostInput) -> i32 {\n    let observer = run NativeDiagnostics.make(NativeReport.make(2, 4096, 32), 64)\n    return run NativeDiagnostics.observe(\n      move observer,\n      effect {\n        return invoke(invokeApplication, move inputs)\n      },\n    )\n  }\n  effect fn start(argc: i32, argv: [*]const ?[*]const u8) -> i32\n  ! HostInputError | OutOfMemoryError | EntrySuspended {\n    let mut allocator = Allocator.systemAllocatorProvider()\n    let inputs = run unsafe NativeHostInput.captureProcess(argc, argv)\n      |> Effect.provideMut<Allocator>(&mut allocator)\n    let provider = OsHostInput.make(move inputs)\n    let execution = run Execution.make(observedApplication(move provider), (), ready)\n      |> Effect.provideMut<Allocator>(&mut allocator)\n    let mut status = Status {complete: false, code: 0}\n    run Execution.drive(move execution, &mut status, complete, suspended)\n    if status.complete == false {\n      fail EntrySuspended {}\n    }\n    return status.code\n  }\n  effect fn startup(argc: i32, argv: [*]const ?[*]const u8) -> i32 {\n    return run Effect.catchAll(start(argc, argv), failed)\n  }\n  /// Receives the platform C process inputs and returns the source startup policy.\n  ///\n  /// # Details\n  ///\n  /// The platform must supply the standard main argument-vector contract. Initialization failures\n  /// return status 1 after best-effort reporting. Application status is returned unchanged.\n  export "C" fn enter(argc: i32, argv: [*]const ?[*]const u8) -> i32 as "main" {\n    let observer = run NativeDiagnostics.make(NativeReport.make(2, 4096, 32), 0)\n    return run NativeDiagnostics.observe(move observer, startup(argc, argv))\n  }\n}\n',
