    runtimeInventory: [],
    namespace: 'OsHostInput',
    source:
      '//! Native HostInput provider backed by an owned process-input snapshot.\n//!\n//! # When to use\n//! Capture NativeHostInput at the application boundary and move it into this provider. Portable\n//! code receives it through the mutable HostInput service and obtains independent owned results.\n//!\n//! # Details\n//! Arguments and environment retain their captured bytes. Working-directory lookup observes the\n//! current process directory on each call. Dropping the provider releases the complete snapshot.\n//!\n//! # Gotchas\n//! Available only on the supported native libc profiles. Capturing foreign input requires that\n//! its storage remain readable and unchanged throughout capture.\n\nstatic if (Intrinsic.targetOperatingSystem() == "darwin" && Intrinsic.targetArchitecture() == "aarch64" && Intrinsic.targetAbi() == "apple" && Intrinsic.profileText("libc") == "system") || (Intrinsic.targetOperatingSystem() == "linux" && Intrinsic.targetAbi() == "gnu" && Intrinsic.profileText("libc") == "gnu" && (Intrinsic.targetArchitecture() == "aarch64" || Intrinsic.targetArchitecture() == "x86_64")) {\n  import silk.allocator { Allocator, OutOfMemoryError }\n  import silk.bytes { Bytes }\n  import silk.host_input { HostInput, HostInputError }\n  import silk.native_host_input { NativeHostInput }\n  import silk.option { Option }\n  import silk.string { String }\n\n  /// An affine HostInput provider owning its argument and environment snapshot.\n  pub struct OsHostInput { inputs: NativeHostInput }\n\n  impl OsHostInput {\n    /// Moves an already captured snapshot into the portable service provider.\n    ///\n    /// # Details\n    /// Construction reads no foreign state and performs no allocation.\n    pub fn make(inputs: NativeHostInput) -> OsHostInput {\n      return OsHostInput { inputs: move inputs }\n    }\n\n    effect fn argumentCount(self: &mut Self) -> usize ! HostInputError {\n      return NativeHostInput.argumentCount(&self.inputs)\n    }\n\n    effect fn argument(self: &mut Self, index: usize) -> Option<Bytes> ! HostInputError | OutOfMemoryError ? &mut Allocator {\n      return run fetch(&self.inputs, true, index, String.utf8Bytes(""))\n    }\n\n    effect fn variable(self: &mut Self, name: &[u8]) -> Option<Bytes> ! HostInputError | OutOfMemoryError ? &mut Allocator {\n      return run fetch(&self.inputs, false, 0, name)\n    }\n\n    effect fn workingDirectory(self: &mut Self) -> Bytes ! HostInputError | OutOfMemoryError ? &mut Allocator {\n      return run NativeHostInput.workingDirectory()\n    }\n  }\n\n  fn lookup(inputs: &NativeHostInput, argument: bool, index: usize, name: &[u8], output: &mut [u8]) -> Option<usize> {\n    if argument { return NativeHostInput.argument(inputs, index, move output) }\n    return NativeHostInput.variable(inputs, name, move output)\n  }\n\n  effect fn fetch(inputs: &NativeHostInput, argument: bool, index: usize, name: &[u8]) -> Option<Bytes> ! OutOfMemoryError ? &mut Allocator {\n    let mut empty = Bytes.make()\n    let found = lookup(inputs, argument, index, name, Bytes.asMutSlice(&mut empty))\n    return match move found {\n      Option<usize>.None => Option.none<Bytes>()\n      Option<usize>.Some { value: length } => {\n        let mut bytes = run Bytes.zeroed(length)\n        let copied = lookup(inputs, argument, index, name, Bytes.asMutSlice(&mut bytes))\n        return Option.some<Bytes>(move bytes)\n      }\n    }\n  }\n\n  impl HostInput for OsHostInput {\n    argumentCount: OsHostInput.argumentCount\n    argument: OsHostInput.argument\n    variable: OsHostInput.variable\n    workingDirectory: OsHostInput.workingDirectory\n  }\n}\n',
