    source:
      '//! Owned anonymous Linux mappings with runtime page-size and alignment checks.\n//!\n//! # When to use\n//!\n//! Use `Mapping.allocate` in a raw Linux composition after startup validates AT_PAGESZ.\n//! Each successful value owns its entire mapping and releases it on structured drop.\n//!\n//! # Gotchas\n//!\n//! Raw pointers do not keep their mapping alive. Fatal traps do not guarantee release.\n\nstatic if Intrinsic.targetOperatingSystem() == "linux" && Intrinsic.profileText("libc") == "none" && (Intrinsic.targetArchitecture() == "x86_64" || Intrinsic.targetArchitecture() == "aarch64") {\n  import silk.raw_linux { RawLinux, MMAP, MUNMAP }\n  import silk.result {Result}\n  import silk.usize\n  /// One affine, zero-initialized anonymous mapping and its aligned usable range.\n  pub struct Mapping {\n    base: usize\n    reserved: usize\n    address: usize\n    requested: usize\n  }\n  impl Drop for Mapping {\n    fn drop(self: &mut Mapping) -> () {\n      let reserved = Intrinsic.replace(self.reserved, 0)\n      if reserved != 0 {\n        let ignored = unsafe RawLinux.syscall2(MUNMAP, self.base, reserved)\n      }\n    }\n  }\n  impl Mapping {\n    /// Allocates a zero-initialized byte range with the requested alignment.\n    ///\n    /// # Details\n    ///\n    /// The caller supplies the process page size from validated AT_PAGESZ. Size must be positive;\n    /// page size and alignment must be powers of two. Invalid values and arithmetic overflow return\n    /// error 22. Mapping failure returns the kernel error. Success owns one complete mapping.\n    pub fn allocate(length: usize, alignment: usize, pageSize: usize) -> Result<Mapping, usize> {\n      if length == 0 || alignment == 0 || pageSize == 0 {\n        return Result.failResult<Mapping, usize>(22)\n      }\n      if (alignment & (alignment - 1)) != 0 || (pageSize & (pageSize - 1)) != 0 {\n        return Result.failResult<Mapping, usize>(22)\n      }\n      let padding = alignment - 1\n      if length > usize.MAX - padding {\n        return Result.failResult<Mapping, usize>(22)\n      }\n      let needed = length + padding\n      if needed > usize.MAX - (pageSize - 1) {\n        return Result.failResult<Mapping, usize>(22)\n      }\n      let reserved = ((needed + (pageSize - 1)) / pageSize) * pageSize\n      let base = unsafe RawLinux.syscall6(MMAP, 0, reserved, 3, 34, usize.MAX, 0)\n      let error = RawLinux.error(base)\n      if error != 0 {\n        return Result.failResult<Mapping, usize>(error)\n      }\n      let owner = Mapping {base: base, reserved: reserved, address: base, requested: length}\n      if base > usize.MAX - padding {\n        return Result.failResult<Mapping, usize>(22)\n      }\n      let address = ((base + padding) / alignment) * alignment\n      let mut mapping = move owner\n      mapping.address = address\n      return Result.succeed<Mapping, usize>(move mapping)\n    }\n    /// Returns the requested usable byte count, excluding alignment padding.\n    pub fn length(self: &Mapping) -> usize {\n      return self.requested\n    }\n    /// Returns the aligned address of the mapping\'s usable range.\n    ///\n    /// # Gotchas\n    ///\n    /// The pointer grants no ownership. Keep the mapping alive and limit accesses to `length` bytes.\n    /// The initial bytes are zero; subsequent reads require the caller to preserve initialization.\n    pub unsafe fn pointer(self: &mut Mapping) -> ?[*]mut u8 {\n      return unsafe RawLinux.pointer(self.address)\n    }\n    /// Releases the complete mapping and consumes its owner.\n    ///\n    /// # Details\n    ///\n    /// Returns zero on success or the positive kernel error. Drop makes no second release attempt.\n    pub fn release(value: Mapping) -> usize {\n      let mut self = move value\n      let reserved = Intrinsic.replace(self.reserved, 0)\n      return RawLinux.error(unsafe RawLinux.syscall2(MUNMAP, self.base, reserved))\n    }\n  }\n}\n',
