    namespace: 'ProcessInputs',
    source:
      '//! Borrowed Linux process inputs decoded from the kernel\'s initial stack.\n//!\n//! # When to use\n//!\n//! Use `ProcessInputs.decode` only at a raw process entry. The process owns all input storage.\n//! Arguments and environment entries remain byte strings; page size comes from AT_PAGESZ.\n//!\n//! # Gotchas\n//!\n//! The decoder requires a complete readable kernel stack image. It does not validate arbitrary\n//! memory. Returned pointers carry no ownership and are valid only while that image remains live.\n\nstatic if Intrinsic.targetOperatingSystem() == "linux" && Intrinsic.profileText("libc") == "none" && (Intrinsic.targetArchitecture() == "x86_64" || Intrinsic.targetArchitecture() == "aarch64") {\n  import silk.pointer {Pointer}\n  import silk.raw_linux { RawLinux }\n  import silk.result {Result}\n  /// Borrowed argument/environment words and a validated runtime page size.\n  pub struct ProcessInputs {\n    arguments: [*]const usize\n    argumentCount: usize\n    environment: [*]const usize\n    environmentCount: usize\n    page: usize\n  }\n  impl ProcessInputs {\n    /// Decodes one complete kernel-provided initial stack without allocation.\n    ///\n    /// # Details\n    ///\n    /// Invalid argv termination or missing, duplicate or non-power-of-two AT_PAGESZ returns error 22.\n    /// Unknown auxiliary-vector keys are ignored. No input is copied or changed.\n    ///\n    /// # Gotchas\n    ///\n    /// The caller must provide aligned readable words through both pointer-vector terminators and\n    /// AT_NULL. Each nonzero argument/environment address must identify a live NUL-terminated string.\n    pub unsafe fn decode(stack: [*]const usize) -> Result<ProcessInputs, usize> {\n      unsafe {\n        let argc = Pointer.read<usize>(Pointer.at<usize>(stack, 0))\n        if argc > 18446744073709551613 {\n          return Result.failResult<ProcessInputs, usize>(22)\n        }\n        let arguments = Pointer.assumeMany<usize>(Pointer.at<usize>(stack, 1))\n        if Pointer.read<usize>(Pointer.at<usize>(arguments, argc)) != 0 {\n          return Result.failResult<ProcessInputs, usize>(22)\n        }\n        let environment = Pointer.assumeMany<usize>(Pointer.at<usize>(stack, argc + 2))\n        let mut count: usize = 0\n        while Pointer.read<usize>(Pointer.at<usize>(environment, count)) != 0 {\n          count = count + 1\n        }\n        let auxv = Pointer.assumeMany<usize>(Pointer.at<usize>(environment, count + 1))\n        let mut index: usize = 0\n        let mut page: usize = 0\n        while true {\n          let key = Pointer.read<usize>(Pointer.at<usize>(auxv, index))\n          if key == 0 {\n            break\n          }\n          let value = Pointer.read<usize>(Pointer.at<usize>(auxv, index + 1))\n          if key == 6 {\n            if page != 0 || value == 0 || (value & (value - 1)) != 0 {\n              return Result.failResult<ProcessInputs, usize>(22)\n            }\n            page = value\n          }\n          index = index + 2\n        }\n        if page == 0 {\n          return Result.failResult<ProcessInputs, usize>(22)\n        }\n        return Result.succeed<ProcessInputs, usize>(\n          ProcessInputs {\n            arguments: arguments,\n            argumentCount: argc,\n            environment: environment,\n            environmentCount: count,\n            page: page,\n          },\n        )\n      }\n    }\n    /// Returns the validated runtime AT_PAGESZ value.\n    pub fn pageSize(self: &ProcessInputs) -> usize {\n      return self.page\n    }\n    /// Returns the number of argument strings, including the program name.\n    pub fn argc(self: &ProcessInputs) -> usize {\n      return self.argumentCount\n    }\n    /// Returns the number of environment strings.\n    pub fn envc(self: &ProcessInputs) -> usize {\n      return self.environmentCount\n    }\n    /// Returns an argument\'s NUL-terminated byte pointer, or null for an absent index.\n    ///\n    /// # Gotchas\n    ///\n    /// The decoder\'s original stack and string storage must remain live. The pointer owns no storage.\n    pub unsafe fn argument(self: &ProcessInputs, index: usize) -> ?[*]const u8 {\n      if index >= self.argumentCount {\n        return unsafe Intrinsic.pointerRequalify<?[*]mut u8, ?[*]const u8>(\n          unsafe RawLinux.pointer(0),\n        )\n      }\n      unsafe {\n        return Intrinsic.pointerRequalify<?[*]mut u8, ?[*]const u8>(\n          RawLinux.pointer(Pointer.read<usize>(Pointer.at<usize>(self.arguments, index))),\n        )\n      }\n    }\n    /// Returns an environment entry\'s NUL-terminated byte pointer, or null for an absent index.\n    ///\n    /// # Gotchas\n    ///\n    /// The decoder\'s original stack and string storage must remain live. The pointer owns no storage.\n    pub unsafe fn variable(self: &ProcessInputs, index: usize) -> ?[*]const u8 {\n      if index >= self.environmentCount {\n        return unsafe Intrinsic.pointerRequalify<?[*]mut u8, ?[*]const u8>(\n          unsafe RawLinux.pointer(0),\n        )\n      }\n      unsafe {\n        return Intrinsic.pointerRequalify<?[*]mut u8, ?[*]const u8>(\n          RawLinux.pointer(Pointer.read<usize>(Pointer.at<usize>(self.environment, index))),\n        )\n      }\n    }\n  }\n}\n',
