    runtimeInventory: ['application', 'assembly', 'machine'],
    namespace: 'RawStart',
    source:
      '//! Explicit source entry for a static non-PIE Linux executable.\n//!\n//! # When to use\n//!\n//! Select this module as the artifact runtime root with libc none and loader entry `_start`.\n//! The application supplies `pub fn main(inputs: &ProcessInputs) -> i32`.\n//!\n//! # Details\n//!\n//! Startup decodes the kernel stack and invokes the application once. Invalid required process\n//! facts exit with status 127. Application return becomes the exit_group status.\n//!\n//! # Gotchas\n//!\n//! This composition provides no suspension storage or terminal report provider. It requires a\n//! synchronous application closure. Fatal traps do not guarantee cleanup or a report.\n\nstatic if Intrinsic.targetOperatingSystem() == "linux" && Intrinsic.profileText("libc") == "none" && (Intrinsic.targetArchitecture() == "x86_64" || Intrinsic.targetArchitecture() == "aarch64") {\n  import Intrinsic.application\n  import silk.raw_linux { RawLinux, EXIT_GROUP }\n  import silk.raw_process_inputs {ProcessInputs}\n  import silk.result {Result}\n  import silk.i32\n\n  static if Intrinsic.targetArchitecture() == "x86_64" {\n    /// Enters from the Linux kernel stack and transfers to the source process initializer.\n    unsafe export "C" fn entry() -> () as "_start" with Intrinsic.machine(\n      naked: true,\n      noReturn: true,\n    ) {\n      return unsafe Intrinsic.assembly<()>(\n        "movq %rsp, %rdi\\nandq $$-16, %rsp\\ncall silk_raw_process_entry\\nud2",\n        "",\n        "",\n        "readwrite",\n        true,\n        true,\n        (),\n      )\n    }\n  } else {\n    /// Enters from the Linux kernel stack and transfers to the source process initializer.\n    unsafe export "C" fn entry() -> () as "_start" with Intrinsic.machine(\n      naked: true,\n      noReturn: true,\n    ) {\n      return unsafe Intrinsic.assembly<()>(\n        "mov x0, sp\\nbl silk_raw_process_entry\\nbrk #0",\n        "",\n        "",\n        "readwrite",\n        true,\n        true,\n        (),\n      )\n    }\n  }\n  /// Decodes the kernel stack, invokes the application and terminates the process.\n  ///\n  /// # Gotchas\n  ///\n  /// Only the raw entry fragment may call this export. Its pointer must identify the complete,\n  /// aligned and readable Linux kernel stack image. The function does not return.\n  export "C" fn invoke(stack: [*]const usize) -> () as "silk_raw_process_entry" {\n    let decoded = unsafe ProcessInputs.decode(stack)\n    let code = match move decoded {\n      Result<ProcessInputs, usize>.Success {value} => application.main(&value)\n      Result<ProcessInputs, usize>.Failure {error} => 127\n    }\n    let status = i32.toUsize(code & 255)\n    return unsafe RawLinux.syscallNoReturn(EXIT_GROUP, status)\n  }\n}\n',
