    runtimeInventory: ['pointerReinterpret', 'pointerRequalify'],
    source:
      '//! Word-wise compiler support with explicit C linkage and no runtime services.\n\nimport silk.pointer { Pointer }\n\n/// Compares unsigned bytes and returns zero, a negative value, or a positive value.\n///\n/// # Details\n///\n/// The first unequal byte determines the sign. Zero-length ranges compare equal. Equal leading\n/// words are skipped eight bytes at a time; the remaining bytes, including any unequal word,\n/// compare one at a time.\n///\n/// # Gotchas\n///\n/// The caller must provide live readable ranges of `count` bytes.\nexport "C" fn memcmp(left: ?[*]const u8, right: ?[*]const u8, count: usize) -> i32 {\n  if count == 0 { return 0 }\n  unsafe {\n    let first = Intrinsic.pointerRequalify<?[*]const u8, [*]const u8>(left)\n    let second = Intrinsic.pointerRequalify<?[*]const u8, [*]const u8>(right)\n    let mut index: usize = 0\n    while count - index >= 8 && Pointer.readUnaligned<u64>(wordAt(first, index)) == Pointer.readUnaligned<u64>(wordAt(second, index)) {\n      index = index + 8\n    }\n    while index < count {\n      let a = Pointer.read<u8>(Pointer.at<u8>(first, index))\n      let b = Pointer.read<u8>(Pointer.at<u8>(second, index))\n      if a < b { return -1 }\n      if a > b { return 1 }\n      index = index + 1\n    }\n    return 0\n  }\n}\n\nunsafe fn wordAt(base: [*]const u8, index: usize) -> *const align(1) u64 {\n  unsafe { return Intrinsic.pointerReinterpret<*const u8, *const align(1) u64>(Pointer.at<u8>(base, index)) }\n}\n',
