      '//! Word-wise compiler support with explicit C linkage and no runtime services.\n\nimport silk.pointer { Pointer }\n\n/// Copies `count` bytes and returns the original destination address.\n///\n/// # Details\n///\n/// Bytes move eight at a time through unaligned word accesses, then one at a time. A destination\n/// above the source copies from the end, so each word is read before any overlapping write.\n///\n/// # Gotchas\n///\n/// The caller must provide live readable source bytes and writable destination bytes.\n/// The ranges can overlap; each output byte receives its original source value.\nexport "C" fn memmove(destination: ?[*]mut u8, source: ?[*]const u8, count: usize) -> ?[*]mut u8 {\n  if count == 0 { return destination }\n  unsafe {\n    let output = Intrinsic.pointerRequalify<?[*]mut u8, [*]mut u8>(destination)\n    let input = Intrinsic.pointerRequalify<?[*]const u8, [*]const u8>(source)\n    if Pointer.addressMany<u8>(destination) > Pointer.addressMany<u8>(source) {\n      let mut end = count\n      while end >= 8 {\n        end = end - 8\n        Pointer.writeUnaligned<u64>(wordAtMut(output, end), Pointer.readUnaligned<u64>(wordAt(input, end)))\n      }\n      while end > 0 {\n        end = end - 1\n        Pointer.write<u8>(Pointer.atMut<u8>(output, end), Pointer.read<u8>(Pointer.at<u8>(input, end)))\n      }\n      return destination\n    }\n    let mut index: usize = 0\n    while count - index >= 8 {\n      Pointer.writeUnaligned<u64>(wordAtMut(output, index), Pointer.readUnaligned<u64>(wordAt(input, index)))\n      index = index + 8\n    }\n    while index < count {\n      Pointer.write<u8>(Pointer.atMut<u8>(output, index), Pointer.read<u8>(Pointer.at<u8>(input, index)))\n      index = index + 1\n    }\n    return destination\n  }\n}\n\nunsafe fn wordAt(base: [*]const u8, index: usize) -> *const align(1) u64 {\n  unsafe { return Intrinsic.pointerReinterpret<*const u8, *const align(1) u64>(Pointer.at<u8>(base, index)) }\n}\n\nunsafe fn wordAtMut(base: [*]mut u8, index: usize) -> *mut align(1) u64 {\n  unsafe { return Intrinsic.pointerReinterpret<*mut u8, *mut align(1) u64>(Pointer.atMut<u8>(base, index)) }\n}\n',
