    source:
      '//! Decoding scanner-validated TOML string tokens into owned UTF-8 text.\n\nimport silk.allocator { Allocator, OutOfMemoryError }\nimport silk.bytes { Bytes }\nimport silk.slice { Slice }\nimport silk.u32\nimport silk.u8\nimport silk.usize\n\n/// Operations on validated TOML string spellings.\npub struct TomlText {}\n\nimpl TomlText {\n  /// Copies validated bytes into owned storage.\n  pub effect fn copy(raw: &[u8]) -> Bytes ! OutOfMemoryError ? &mut Allocator {\n    let mut output = Bytes.make()\n    run Bytes.append(&mut output, raw)\n    return move output\n  }\n\n  /// Decodes a complete quoted token, including multiline trimming and escapes.\n  pub effect fn decode(raw: &[u8], literal: bool, multiline: bool)\n    -> Bytes ! OutOfMemoryError ? &mut Allocator {\n    let mut delimiter: usize = 1\n    if multiline { delimiter = 3 }\n    let mut start = delimiter\n    let end = raw.length - delimiter\n    if multiline {\n      if raw[start] == 13 { start = start + usize.ONE }\n      if raw[start] == 10 { start = start + usize.ONE }\n    }\n    let mut output = Bytes.make()\n    run Bytes.reserveExact(&mut output, end - start)\n    let mut index = start\n    let mut segment = start\n    while index < end {\n      if literal || raw[index] != 92 { index = index + usize.ONE\n        continue }\n      if segment < index {\n        run Bytes.append(&mut output, Slice.view<u8>(raw, segment, index - segment))\n      }\n      index = index + usize.ONE\n      let escaped = raw[index]\n      if multiline && (escaped == 32 || escaped == 9 || escaped == 10 || escaped == 13) {\n        while index < end && (raw[index] == 32 || raw[index] == 9 || raw[index] == 10 || raw[index] == 13) {\n          index = index + usize.ONE\n        }\n      } else if escaped == 120 || escaped == 117 || escaped == 85 {\n        let mut digits: usize = 8\n        if escaped == 120 { digits = 2 }\n        else if escaped == 117 { digits = 4 }\n        let mut scalar: u32 = 0\n        let mut digit = usize.ZERO\n        while digit < digits {\n          let byte = raw[index + usize.ONE + digit]\n          let mut value = u8.toU32(byte - 48)\n          if byte >= 65 && byte <= 70 { value = u8.toU32(byte - 65) + 10 }\n          if byte >= 97 && byte <= 102 { value = u8.toU32(byte - 97) + 10 }\n          scalar = scalar * 16 + value\n          digit = digit + usize.ONE\n        }\n        run appendScalar(&mut output, scalar)\n        index = index + digits + usize.ONE\n      } else {\n        let mut decoded = escaped\n        if escaped == 98 { decoded = 8 }\n        else if escaped == 116 { decoded = 9 }\n        else if escaped == 110 { decoded = 10 }\n        else if escaped == 102 { decoded = 12 }\n        else if escaped == 114 { decoded = 13 }\n        else if escaped == 101 { decoded = 27 }\n        let one = [decoded]\n        run Bytes.append(&mut output, &one)\n        index = index + usize.ONE\n      }\n      segment = index\n    }\n    if segment < end { run Bytes.append(&mut output, Slice.view<u8>(raw, segment, end - segment)) }\n    return move output\n  }\n}\n\neffect fn appendScalar(output: &mut Bytes, scalar: u32) -> () ! OutOfMemoryError ? &mut Allocator {\n  if scalar < 128 {\n    let encoded = [u32.toU8(scalar)]\n    return run Bytes.append(&mut output.*, &encoded)\n  }\n  if scalar < 2048 {\n    let encoded = [u32.toU8(192 + scalar / 64), u32.toU8(128 + scalar % 64)]\n    return run Bytes.append(&mut output.*, &encoded)\n  }\n  if scalar < 65536 {\n    let encoded = [u32.toU8(224 + scalar / 4096), u32.toU8(128 + scalar / 64 % 64),\n      u32.toU8(128 + scalar % 64)]\n    return run Bytes.append(&mut output.*, &encoded)\n  }\n  let encoded = [u32.toU8(240 + scalar / 262144), u32.toU8(128 + scalar / 4096 % 64),\n    u32.toU8(128 + scalar / 64 % 64), u32.toU8(128 + scalar % 64)]\n  return run Bytes.append(&mut output.*, &encoded)\n}\n',
