    module: 'silk/zstd',
    path: 'silk/zstd.silk',
    sourceIdentity: 'silk/zstd',
    digest: '292240e2e1da079b1b06416b61436131f4b6e4e236fc82e3a0c05d465eac945e',
    documentation: 'silk/zstd.silk',
